INSERT INTO {DBNICK}_store (id, name, descr, no_visible, kind_key, status_key, create_time, update_time, edit_time) VALUES (1, 'How to use the charter', '<p>The charter is how this store works: its processes, the duties of the staff, the rules for orders, suppliers, stock and goods, and the technical set-up of the store. People read it in the Program; the AI assistant reads it before any work.</p><h3>Where it lives</h3><p>Every document is an item of the <abbr title="store.kind_key = kDoc">Document</abbr> type in the <abbr title="topic.skey = CHARTER">Charter</abbr> section. A section holds what everyone the topic concerns must know; its subsections hold the details and are open only to the groups who need them.</p><h3>State of a document</h3><table><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><abbr title="store.status_key = kDocDraft">Draft</abbr></td><td>the document is being written and is not a rule yet</td></tr><tr><td><abbr title="store.status_key = kDocRelease">Ready</abbr></td><td>the owner has approved it; the staff and the assistant work by it</td></tr></tbody></table><p>Text in <i>italics</i> is not confirmed: it stays in its place, and the owner answers what is marked.</p><h3>How a document is written</h3><p>The assistant gathers what is known on the topic — old regulations, other documents, the scripts and the data of the store — and asks the owner one question at a time. It writes how things are done and where they are set, without guesses. How the text is laid out is told in <abbr title="store.id = 4">How to write documents</abbr>.</p><h3>When the charter is silent</h3><p>The assistant says so and asks the owner. The answer becomes a new document or a change to an existing one.</p><h3>Changes</h3><p>Every significant change is announced in <abbr title="store.id = 2">What’s new</abbr>.</p>', 1, 'kDoc', 'kDocRelease', NOW(), NOW(), NOW());
INSERT INTO {DBNICK}_store (id, name, descr, no_visible, kind_key, status_key, create_time, update_time, edit_time) VALUES (2, 'What’s new', '<p>News of the charter: new documents, changed rules, documents made ready. Read it once a day — the assistant shows you what has appeared since your last reading.</p><p>A record is one line: the document and what holds now. The newest records are on top, under their date; records older than a year are removed. Small edits — typos, wording — are not recorded.</p><h3>Start</h3><ul><li><abbr title="store.id = 1">How to use the charter</abbr> — the charter is started.</li></ul>', 1, 'kDoc', 'kDocRelease', NOW(), NOW(), NOW());
INSERT INTO {DBNICK}_store (id, name, descr, no_visible, kind_key, status_key, create_time, update_time, edit_time) VALUES (3, 'Catalog structure', '<p>How the catalog of the store is organised: the sections with goods, who keeps them and how goods get into them.</p><h3>Sections</h3><p>Goods stand in the <abbr title="topic.skey = SHOP">Shop</abbr> branch, in sections of the <abbr title="topic.kind_key = kGoods">Goods</abbr> type; documents of the charter are in sections of the <abbr title="topic.kind_key = kDoc">Documents</abbr> type. <i>An item stands in one section only / in several sections.</i></p><p><i>Who creates, moves and removes sections.</i></p><h3>Goods</h3><p><i>Where new goods come from — supplier price lists, manual entry — and who describes them before they reach the storefront.</i></p><p><i>What happens to goods that are no longer sold.</i></p>', 1, 'kDoc', 'kDocDraft', NOW(), NOW(), NOW());
INSERT INTO {DBNICK}_store (id, name, descr, no_visible, kind_key, status_key, create_time, update_time, edit_time) VALUES (4, 'How to write documents', '<p>Documents of the charter have two readers: a person in the Program and the AI assistant. The layout makes the text easy for both.</p><h3>Hints for the assistant</h3><p>Technical names hide in an <code>abbr</code> hint: the person reads plain words, the assistant sees in <code>title</code> what exactly is meant.</p><table><thead><tr><th>What</th><th>Hint</th><th>Example</th></tr></thead><tbody><tr><td>field and value</td><td><code>table.field = value</code>, the table without prefix; several conditions joined with <code>AND</code>, inequality <code>!=</code></td><td><abbr title="store.status_key = kDocRelease">Ready</abbr></td></tr><tr><td>document</td><td><code>store.id = number</code></td><td><abbr title="store.id = 1">How to use the charter</abbr></td></tr><tr><td>section</td><td><code>topic.skey = key</code></td><td><abbr title="topic.skey = CHARTER">Charter</abbr></td></tr><tr><td>setting</td><td>the key of the setting; in the text, what it means</td><td></td></tr><tr><td>AI tool</td><td>the address of the tool and the command</td><td><abbr title="MELBIS_AGENT_STORE_BROWSE CmdReadDescr">text of a document</abbr></td></tr></tbody></table><p>A key that stands in the text itself — a mark or a code — goes into <code>code</code>. The value of a setting is never copied into a document: the value changes, the document stays.</p><h3>Not confirmed</h3><p>What is not confirmed yet is written in <i>italics</i> in its place, never gathered into a separate block: the text stays whole, and the owner answers what is marked.</p><h3>Text</h3><p>Write concretely: how a thing is done and where it is set, without guesses and general words. Lists only for real enumerations — ways, conditions, actions; the rest in sentences.</p><p>A section of the charter holds what everyone the topic concerns must know; its subsections hold the details open only to the groups who need them. Documents are small, one topic each; empty ones are not created.</p><h3>Markup</h3><p>Plain HTML without classes or styles: <code>p</code>, <code>h3</code>, <code>ul</code>, <code>ol</code>, <code>li</code>, <code>b</code>, <code>i</code>, <code>code</code>, <code>abbr</code>, <code>table</code>, <code>br</code>.</p><h3>Notes of the assistant</h3><p>The assistant writes its own notes about the store the same way: the same hints, italics and markup. That way they are easy to read in the Program next to the documents of the charter.</p>', 1, 'kDoc', 'kDocRelease', NOW(), NOW(), NOW());
